import{_ as s,o as i,c as e,a5 as n}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"79. C 项目的代码审查清单","description":"The Little Book of C 中文版 — 79. C 项目的代码审查清单","frontmatter":{"title":"79. C 项目的代码审查清单","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","08-调试测试与 profiling","中文"],"description":"The Little Book of C 中文版 — 79. C 项目的代码审查清单","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":79,"sidebarWeight":79,"alternateZh":"/posts/c教程/zh-CN/08-调试测试与 profiling/079-Code Review Checklist for C Projects","alternateEn":"/posts/c教程/en-US/08-Debugging Testing Profiling/079-Code Review Checklist for C Projects"},"headers":[],"relativePath":"posts/c教程/zh-CN/08-调试测试与 profiling/079-Code Review Checklist for C Projects.md","filePath":"posts/c教程/zh-CN/08-调试测试与 profiling/079-Code Review Checklist for C Projects.md","lastUpdated":1790163617000}'),l={name:"posts/c教程/zh-CN/08-调试测试与 profiling/079-Code Review Checklist for C Projects.md"};function t(p,a,o,c,d,r){return i(),e("div",null,[...a[0]||(a[0]=[n(`<p>[English version](/posts/c教程/en-US/08-Debugging Testing Profiling/079-Code Review Checklist for C Projects)</p><p>在你的 C 程序投入生产（甚至是你提交的作业）之前，它应该通过最后一次测试，即代码审查。您或您的团队成员在这里查看代码不仅是为了正确性，也是为了清晰度、安全性和可维护性。</p><p>将此视为起飞前您的个人飞行员清单。每个伟大的 C 程序员都有一个。</p><h4 id="步骤-1-可读性和结构" tabindex="-1">步骤 1. 可读性和结构 <a class="header-anchor" href="#步骤-1-可读性和结构" aria-label="Permalink to &quot;步骤 1. 可读性和结构&quot;">​</a></h4><ul><li>文件是否按逻辑组织（<code>src/</code>,<code>include/</code>,<code>tests/</code>)?</li><li>标题是否干净，是否有包含防护？</li><li>职能是否简短且重点突出（每个职能都有一个目的）？</li><li>名字有意义吗（<code>count_users()</code>比<code>doit()</code>)?</li><li>缩进是否一致且可读？</li><li>评论是否清晰且相关，而不仅仅是噪音？</li></ul><p>小代码示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Bad</span></span>
<span class="line"><span>void d(int a, int b) { printf(&quot;%d\\n&quot;, a+b); }</span></span>
<span class="line"><span>// Good</span></span>
<span class="line"><span>void print_sum(int a, int b) {</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, a + b);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>可读的代码会自我解释。</p><h4 id="步骤-2-割台卫生" tabindex="-1">步骤 2. 割台卫生 <a class="header-anchor" href="#步骤-2-割台卫生" aria-label="Permalink to &quot;步骤 2. 割台卫生&quot;">​</a></h4><ul><li>每个<code>.h</code>文件必须有一个包含保护：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#ifndef MATH_UTILS_H</span></span>
<span class="line"><span>#define MATH_UTILS_H</span></span>
<span class="line"><span>// declarations</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><ul><li>标题应该声明，而不是定义。</li><li>除非合理，否则没有全局变量。</li><li>使用<code>static inline</code>小心（仅适用于小型公用事业）。</li></ul><h4 id="步骤-3-内存安全" tabindex="-1">步骤 3. 内存安全 <a class="header-anchor" href="#步骤-3-内存安全" aria-label="Permalink to &quot;步骤 3. 内存安全&quot;">​</a></h4><ul><li>每一个<code>malloc</code>一定有对应的<code>free</code>.</li><li>检查所有分配结果：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>p = malloc(size);</span></span>
<span class="line"><span>if (!p) { perror(&quot;malloc&quot;); exit(1); }</span></span></code></pre></div><ul><li>避免悬空指针：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>free(p);</span></span>
<span class="line"><span>p = NULL;</span></span></code></pre></div><ul><li>使用 Valgrind 或 AddressSanitizer 确保无泄漏。</li></ul><h4 id="步骤-4-指针规则" tabindex="-1">步骤 4. 指针规则 <a class="header-anchor" href="#步骤-4-指针规则" aria-label="Permalink to &quot;步骤 4. 指针规则&quot;">​</a></h4><ul><li>在取消引用之前检查空指针。</li><li>不要返回指向局部变量的指针：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int* bad(void) {</span></span>
<span class="line"><span>    int x = 10;</span></span>
<span class="line"><span>    return &amp;x; // wrong: stack memory</span></span>
<span class="line"><span>}</span></span></code></pre></div><ul><li>文件所有权：谁分配，谁释放。</li></ul><h4 id="步骤-5-错误处理" tabindex="-1">步骤 5. 错误处理 <a class="header-anchor" href="#步骤-5-错误处理" aria-label="Permalink to &quot;步骤 5. 错误处理&quot;">​</a></h4><ul><li>始终检查函数返回值：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if (fwrite(buf, 1, len, file) != len) {</span></span>
<span class="line"><span>    perror(&quot;fwrite&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><ul><li>使用有意义的错误消息。</li><li>更喜欢返回错误代码而不是默默地忽略失败。</li><li>对于图书馆，请使用<code>errno</code>或您自己的错误枚举。</li></ul><h4 id="步骤-6-未定义行为预防" tabindex="-1">步骤 6. 未定义行为预防 <a class="header-anchor" href="#步骤-6-未定义行为预防" aria-label="Permalink to &quot;步骤 6. 未定义行为预防&quot;">​</a></h4><ul><li>没有未初始化的变量。</li><li>没有越界数组访问。</li><li>无符号整数溢出。</li><li>免费后不使用。</li><li>编译：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -Wall -Wextra -Wpedantic -fsanitize=undefined,address</span></span></code></pre></div><p>修复所有警告，将其视为错误。</p><h4 id="步骤-7-可移植性" tabindex="-1">步骤 7. 可移植性 <a class="header-anchor" href="#步骤-7-可移植性" aria-label="Permalink to &quot;步骤 7. 可移植性&quot;">​</a></h4><ul><li>不要假设<code>int</code>是 32 位或<code>char</code>已签署。</li><li>使用<code>&lt;stdint.h&gt;</code>类型（<code>int32_t</code>,<code>uint64_t</code>).</li><li>使用<code>size_t</code>用于尺寸和索引。</li><li>除非包装，否则避免使用特定于平台的 API。</li><li>在多个编译器上进行测试（<code>gcc</code>,<code>clang</code>,<code>tinycc</code>).</li></ul><h4 id="步骤-8-测试和验证" tabindex="-1">步骤 8. 测试和验证 <a class="header-anchor" href="#步骤-8-测试和验证" aria-label="Permalink to &quot;步骤 8. 测试和验证&quot;">​</a></h4><ul><li>每个可能失败的功能都必须至少进行一次测试。</li><li>边缘情况：空输入、零值、大输入。</li><li>测试应该自动运行：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make test</span></span></code></pre></div><ul><li>将结果与已知良好的输出进行比较。</li><li>记录如何重现测试结果。</li></ul><h4 id="步骤-9-文档" tabindex="-1">步骤 9. 文档 <a class="header-anchor" href="#步骤-9-文档" aria-label="Permalink to &quot;步骤 9. 文档&quot;">​</a></h4><ul><li>为每个文件添加一个短标题：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/* math_utils.c</span></span>
<span class="line"><span> * Simple math helpers.</span></span>
<span class="line"><span> * Author: Your Name</span></span>
<span class="line"><span> * License: MIT</span></span>
<span class="line"><span> */</span></span></code></pre></div><ul><li>注释棘手的代码，但不要注释显而易见的代码。</li><li>维持一个<code>README.md</code>解释构建和运行步骤。</li><li>对您的代码进行版本控制 (Git)。编写有意义的提交消息。</li></ul><h4 id="步骤-10-小代码-应用清单" tabindex="-1">步骤 10. 小代码：应用清单 <a class="header-anchor" href="#步骤-10-小代码-应用清单" aria-label="Permalink to &quot;步骤 10. 小代码：应用清单&quot;">​</a></h4><p>让我们看一个小例子：</p><p>原来的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int *make_array(int n){</span></span>
<span class="line"><span>  int arr[n]; for(int i=0;i&lt;n;i++) arr[i]=i; return arr;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>复习笔记：</p><ul><li>返回指向本地数组的指针 → UB</li><li>魔法循环风格→不可读</li><li>缺少输入验证</li></ul><p>固定的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int *make_array(int n) {</span></span>
<span class="line"><span>    if (n &lt;= 0) return NULL;</span></span>
<span class="line"><span>    int *arr = malloc(n * sizeof(int));</span></span>
<span class="line"><span>    if (!arr) { perror(&quot;malloc&quot;); return NULL; }</span></span>
<span class="line"><span>    for (int i = 0; i &lt; n; i++) arr[i] = i;</span></span>
<span class="line"><span>    return arr;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>通过清单 ✅</p><ul><li>安全、清晰、便携。</li></ul><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>检查表可以建立纪律和一致性。它确保：</p><ul><li>干净、可维护的代码。</li><li>减少碰撞和泄漏。</li><li>更轻松的调试和入门。</li><li>复杂系统的长期稳定性。</li></ul><p>每个高质量的 C 项目都使用一个，从开源库到内核。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><ol><li>选取一个旧的 C 程序并使用此清单进行检查。 2.修复内存泄漏，添加错误检查，清理命名。</li><li>在打开所有警告的情况下进行编译。 4.通过AddressSanitizer或Valgrind运行它。</li><li>记录所有内容，然后对下一个项目重复此操作。</li></ol><p>接下来，您将通过实践练习来结束本调试章节：逐步修复实际内存和逻辑错误。</p>`,57)])])}const g=s(l,[["render",t]]);export{u as __pageData,g as default};
